svg.script:
(async () => {
  const status = document.getElementById('status');
  try {
    const base = new URL('./', location.href);
    const registration = await navigator.serviceWorker.register(new URL('static-worker.mjs', base), {
      scope: base.pathname, type: 'module', updateViaCache: 'none'
    });
    const worker = registration.active || registration.installing || registration.waiting;
    if (!worker) throw new Error('The browser worker did not start.');
    if (worker.state !== 'activated') await new Promise((resolve, reject) => {
      function check() {
        if (worker.state === 'activated') resolve();
        if (worker.state === 'redundant') reject(new Error('The browser worker failed.'));
      }
      worker.addEventListener('statechange', check);
      check();
    });
    const app = document.getElementById('app');
    app.src = new URL('index.html', base).href;
    app.style.display = 'block';
    status.remove();
  } catch (error) {
    status.textContent = 'Could not open GN-Math. ' + error.message;
  }
})();
